def chunk(text, size, overlap):
    step = size - overlap
    chunks = []
    for start in range(0, len(text) - size + 1, step):
        chunks.append(text[start:start + size])
    if chunks and not text.endswith(chunks[-1]):
        chunks.append(text[-size:])
    return chunks

